using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using Microsoft.UI.Xaml.Input;namespace UPM.SiteManager.Views;public sealed partial class IntakePage:Page{public IntakePage()=>InitializeComponent();void DragOver(object s,DragEventArgs e){e.AcceptedOperation=Windows.ApplicationModel.DataTransfer.DataPackageOperation.Copy;}async void Drop(object s,DragEventArgs e){if(!e.DataView.Contains(Windows.ApplicationModel.DataTransfer.StandardDataFormats.StorageItems))return;foreach(var item in await e.DataView.GetStorageItemsAsync())Queue.Items.Add(item.Path);}}
